#!/usr/bin/env python3
"""Render docs/calibration/solid_gci.md from evidence/fem_solid/gci/*_gci.json (PR-0.30.3)."""
import glob, json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
rows = [json.load(open(f)) for f in sorted(glob.glob(os.path.join(ROOT, 'evidence', 'fem_solid', 'gci', '*_gci.json')))]
L = ["# Solid tip submodel — 3-level mesh convergence / GCI (PR-0.30.3)", "",
     "Generated by `fem_solid/gci_report.py` from `evidence/fem_solid/gci/*_gci.json`; produced with `fem_solid/convergence.py`.",
     "The levels refine the plate triangulation and the through-thickness layers together, r = 2: (NSUB, NL) = (0,2) → (1,4) → (2,8).",
     "Load is 1.82 N·m chord torque with a 2 mm patch, clamped at R_CUT 30 mm. The solver is dolfinx P2 + PETSc GAMG (PR-0.30.2).",
     "GCI follows Roache with Fs = 1.25. The quantity is the peak von Mises in the 4–15 mm tip zone; the bar is GCI_fine ≤ 3 %.", "",
     "| design | dofs (coarse / mid / fine) | σvm nodal-max MPa (C / M / F) | p | GCI fine | nodal-max SF (fine, ± band) | σvm nodal-avg MPa (F) | GCI avg | elem metric |",
     "|---|---|---|---|---|---|---|---|---|"]
ok = True
for d in rows:
    lv = d['levels']; m = d['vm_nodal_max_MPa']; a = d['vm_nodal_avg_MPa']; sf = d['SF_nodal_max']
    ok &= m['gci_fine'] <= 0.03
    p = f"{m['p']:.2f}" if m['p'] else 'osc.'
    dofs = ' / '.join(str(x['n_dof']) for x in lv); vms = ' / '.join('%.1f' % x['vm_nodal_max_MPa'] for x in lv)
    L.append(f"| {d['design']} | {dofs} | {vms} | {p} | "
             f"**{100 * m['gci_fine']:.2f} %** | {sf['fine']:.3f} [{sf['lo']:.3f}, {sf['hi']:.3f}] | {a['fine']:.1f} | {100 * a['gci_fine']:.2f} % | — |")
L += ["", f"Result: {'all' if ok else 'NOT all'} {len(rows)} designs meet GCI_fine ≤ 3 % on the governing nodal-max σvm.",
      "The coarse level (NSUB 0, NL 2) is far from asymptotic; the wave production setting (NSUB 1, NL 4) sits within a few % of the fine level.",
      "Element-mean σvm is not reported: it under-reads peaks and is not a gate metric."]
open(os.path.join(ROOT, 'docs', 'calibration', 'solid_gci.md'), 'w').write('\n'.join(L) + '\n'); print('\n'.join(L))
